import numpy as np
from scipy.optimize import least_squares
def build(p,maxk):
    a,b,d=p
    g=1-np.exp(-a*t**b); u=t**d
    cols=[]
    for T in [np.ones_like(t),g,u,g*u]:
        for k in range(maxk+1):
            cols.append(T*P**k)
    return np.column_stack(cols)
def res(p,maxk):
    X=build(p,maxk)
    c,*_=np.linalg.lstsq(X,dP_dt,rcond=None)
    return dP_dt-X@c
for maxk in [2,3]:
    best=None
    for s in [[0.25,1.2,1.0],[0.1,2,0.5],[0.5,1,1.5],[0.2,1.5,0.8]]:
        try:
            r=least_squares(lambda p: res(p,maxk), s)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    X=build(best.x,maxk); c,*_=np.linalg.lstsq(X,dP_dt,rcond=None)
    print(maxk, best.x, np.sqrt(np.mean(best.fun**2)), 'NMSE',np.mean(best.fun**2)/np.var(dP_dt))
    print(np.round(c,4))
